 function commitEquipment(name,slot,id,fromBag=false){
  try{
   const latest=JSON.parse(localStorage.getItem(key)||'null')||JSON.parse(JSON.stringify(state));
   EquipmentSystem.equip(latest,state.mode,name,slot,id);
   localStorage.setItem(key,JSON.stringify(latest));
   state.equipment=latest.equipment;
   if(page==='bag')renderBag();
   if(fromBag){showBagEquipment(fromBag);}else showEquipment(name);
   toast(id===null?'已卸下裝備。':'已更新'+name+'的'+EquipmentSystem.slots[slot]+'。');
  }catch(error){toast(error.message||'裝備未能保存，請稍後再試。');}
 }


